  function triggerEvent(kind,locationId,origin=kind==='explore'?'explore':'travel'){const options=candidates(kind,locationId);if(!options.length)return null;const depth=state.expedition.active?state.expedition.depth:0,total=options.reduce((sum,event)=>sum+eventWeight(event,depth,locationId),0);let roll=Math.random()*total,selected=options[options.length-1];for(const event of options){roll-=eventWeight(event,depth,locationId);if(roll<=0){selected=event;break;}}const guaranteed=options.find(e=>e.personalStory&&!e.storySide&&state.personalStory.missedEncounters>=3);const callback=L.priority(state,locationId);const main=M.priority(state,locationId);if(callback&&options.some(e=>e.id===callback.id))selected=callback;if(guaranteed)selected=guaranteed;if(main)selected=main;if(selected.personalStory&&!selected.storySide)state.personalStory.missedEncounters=0;if(state.expedition.active){state.expedition.history.push(selected.id);state.expedition.history=state.expedition.history.slice(-32);}state.recentEvents.push(selected.id);state.recentEvents=state.recentEvents.slice(-3);return startEvent(clone(selected),origin);}
