  function claimEventCompletion(){const event=state.event,flow=event?.flow;if(!flow||flow.phase!=='result'||flow.pending?.nextStage||flow.pending?.nextEvent||flow.flags.completionPaid)return;if(W.events.find(e=>e.id===event.id)?.unique&&!state.seenEvents.includes(event.id))state.seenEvents.push(event.id);const key=completionKey(event);flow.flags.completionPaid=true;flow.completionXP=key&&!state.eventXPClaims.includes(key)?({common:8,uncommon:12,rare:20,very_rare:30,special:28,unique:36,legendary:40}[event.rarity||'common']||8):0;if(key&&!state.eventXPClaims.includes(key))state.eventXPClaims.push(key);if(flow.completionXP)grantXP(flow.completionXP,'событие завершено');}
