  function showEventResult(text,pending={}){if(!state.event)return;const flow=state.event.flow;flow.phase='result';flow.pending={nextStage:pending.nextStage||null,nextEvent:pending.nextEvent||null,finish:Boolean(pending.finish),winText:pending.winText||'',fleeText:pending.fleeText||''};flow.completionXP=0;flow.resultText=text||'Решение принято. Пора решить, продолжать ли вылазку.';state.event.text=flow.resultText;state.event.choices=[{label:flow.pending.nextStage||flow.pending.nextEvent?'Следующий этап':'Продолжить',action:'advance'}];state.mode='event';state.panelReturn=null;claimEventCompletion();emit();}
  function finishEventFlow(returnToOrigin=false){const flow=state.event?.flow,origin=flow?.origin,search=origin==='explore'&&state.expedition.active,cost=X.cost(state.expedition.depth);if(search&&!returnToOrigin&&state.player.stamina<cost)return notify('Для следующего поиска нужно '+cost+' выносливости. Вернись и передохни.');deferEmission++;try{claimEventCompletion();const home=state.expedition.originLocationId;state.event=null;state.panelReturn=null;if(returnToOrigin){state.travelTo=null;if(search&&W.locations[home]){state.player.location=home;discover(home);if(!state.visited.includes(home))state.visited.push(home);const t=state.expedition.summary;log('Вылазка завершена: '+state.expedition.depth+' встреч · '+t.hours+' ч · '+t.kills+' побед · '+t.xp+' XP.');}if(search){L.onReturn(state);F.finish(state);expeditionReturn=true;}resetExploration();state.mode='play';return;}if(origin==='travel'&&state.travelTo){arrive(state.travelTo);return;}if(search){state.player.location=home;explore();}else{resetExploration();state.mode='play';}}finally{deferEmission--;emit();}}
  function advanceEvent(){const event=state.event,flow=event?.flow;if(!event||!flow)return;const pending=flow.pending||{};if(pending.nextStage&&!W.events.find(e=>e.id===event.id)?.stages?.some(s=>s.id===pending.nextStage)){console.warn('[ZoneRPG] Недопустимое продолжение события',{eventId:event.id,nextStage:pending.nextStage});return notify('Не удалось открыть следующий этап. Сохрани вылазку; текущая встреча сохранена.');}if(pending.nextEvent&&!W.events.some(e=>e.id===pending.nextEvent)){console.warn('[ZoneRPG] Неизвестное продолжение события',pending.nextEvent);return notify('Не удалось открыть продолжение. Текущая встреча сохранена.');}if(pending.nextStage){const definition=W.events.find(item=>item.id===event.id);if(definition&&stagesOf(definition).some(stage=>stage.id===pending.nextStage)){setEventStage(definition,pending.nextStage,flow);emit();return;}}if(pending.nextEvent){const next=W.events.find(item=>item.id===pending.nextEvent);if(next&&!flow.chain.includes(next.id)&&flow.chain.length<8){startEvent(next,flow.origin,flow);emit();return;}}finishEventFlow();}
