  function travel(id){if(state.expedition.active)return notify('Нельзя перейти в другую локацию во время вылазки.');if(state.event||state.combat)return notify('Сначала закончи текущую встречу.');const loc=W.locations[state.player.location];if(!M.neighbors(state,state.player.location).includes(id)||!unlocked(id)||routeBlocked(state.player.location,id))return notify('Этот путь пока закрыт.');if(state.player.stamina<4)return notify('Сил не хватает. Отдохни или выпей энергетик.');window.ZoneRPGAudio?.playUISound('forward');const dest=W.locations[id],p=state.player;resetExploration();state.travelTo=id;const cost=5+dest.danger*2+(weight()>capacity()?8:0);p.stamina=clamp(p.stamina-cost,0,finalStats().maxStamina);p.hunger=clamp(p.hunger+needDrain(5+dest.danger));p.thirst=clamp(p.thirst+needDrain(7+dest.danger));advanceClock(1);const res=passive();p.radiation=clamp(p.radiation+dest.rad*.15*(1-res.radResist)+res.radPerTrip);if(p.radiation>=80){const dose=Math.ceil((p.radiation-75)/10);p.health=clamp(p.health-dose,0,finalStats().maxHealth);notify(`Критический фон повреждает здоровье: −${dose}.`);}p.health=clamp(p.health-(p.hunger>80?3:0)-(p.thirst>80?4:0),0,finalStats().maxHealth);if(p.radiation>=20)p.stamina=clamp(p.stamina-(p.radiation>=50?8:3),0,finalStats().maxStamina);log(`Переход · ${dest.name}: −${cost} выносливости, +${window.ZoneRPGFormat.percent(5+dest.danger)} голода, +${window.ZoneRPGFormat.percent(7+dest.danger)} жажды.`);if(p.health<=0)return die();const chance=eventChance(id);if(Math.random()*100<chance){const e=triggerEvent('travel',id);if(e){emit();return;}}arrive(id);}
  function setAmbientEvent(){const loc=W.locations[state.player.location],intro=state.player.trips===0?S.BACKGROUNDS[state.backgroundId].intro:'';state.event={id:'arrival_'+state.player.trips,category:'Локация',text:(intro?intro+' ':loc.layout+'. ')+loc.description,choices:[{label:'Осмотреться',action:'dismiss'},{label:'Открыть карту',action:'map'}],flow:{version:1,stageId:'arrival',stageIndex:0,phase:'choices',origin:'arrival',chain:[],visitedStages:['arrival'],claimedActions:[],flags:{},pending:null,resultText:'',lastChoice:''}};state.mode='event';}
