  function advanceClock(hours){state.player.time=(state.player.time+hours)%24;const before=state.worldClock;state.worldClock+=hours;if(state.expedition.active)state.expedition.summary.hours+=hours;L.tick(state,before);window.ZoneRPGShops.sync(state);}
