        state.fieldJournal.unread.rumors=[...new Set([...state.fieldJournal.unread.rumors,rumor.id])].slice(-64);F.feedback('rumor');if(firstHeard)grantXP(8,'новый слух');outcome='Вы узнали новый слух. '+rumor.title+'. Слух: '+rumor.text+(rumor.consequence?'':L.rumor(state,loc));
