  function retreatChance(){const e=state.combat?.enemy;return clamp(58+state.player.stamina*.18+(state.attributes.agility-2)*3-W.locations[state.player.location].danger*4-(e?.evasion||0)*50-(e?.accuracy||0)*6,15,90);}
  function reload(ref){const selected=ref?findItem(ref):weaponItem(),id=selected&&I.items[selected.id]?.type==='weapon'?selected.id:weaponItem()?.id,weapon=I.weapons[I.items[id]?.weaponId];if(!weapon)return notify('Нет оружия в руках.');if(!weapon.ammoType)return notify('Нож не требует перезарядки.');const need=weapon.magazine-(state.magazines[id]||0),have=count(weapon.ammoType);if(need<=0)return notify('Магазин уже полон.');if(!have)return notify('Нет боеприпасов '+I.items[weapon.ammoType].name+'.');const n=Math.min(need,have);remove(weapon.ammoType,n);state.magazines[id]=(state.magazines[id]||0)+n;log('Перезарядка: '+I.items[id].name+' · '+n+' шт.');window.ZoneRPGAudio?.play('reload');if(state.combat){combatLog('Перезаряжено: '+n+' шт. за '+weapon.reloadTime.toFixed(1)+' с.');enemyHit();}else notify('Магазин '+I.items[id].name+': '+state.magazines[id]+'/'+weapon.magazine+'.');}
  function combatUse(id){if(!state.combat)return;const index=state.inventory.findIndex(x=>x.id===id);if(index<0)return notify('Предмета нет в рюкзаке.');useItem(index);if(state.combat)enemyHit();}
  function flee(){if(!state.combat)return;if(state.combat.retreatLocked)return notify('Этот бой нужно закончить: путь отрезан.');const flow=state.event?.flow?.phase==='combat'?state.event.flow:null,chance=retreatChance();if(Math.random()*100<chance){combatLog(`Уход удался (шанс ${window.ZoneRPGFormat.percent(chance)}).`);state.combat=null;state.player.stamina=clamp(state.player.stamina-8);if(flow){state.mode='event';showEventResult(flow.pending?.fleeText||'Ты отрываешься от противника и возвращаешься к событию.',flow.pending||{});return;}state.event=null;state.mode='play';state.panelReturn=null;if(state.travelTo)arrive(state.travelTo);else emit();}else{combatLog(`Не удалось оторваться (шанс ${window.ZoneRPGFormat.percent(chance)}).`);state.player.stamina=clamp(state.player.stamina-10);enemyHit();}}
  function useItem(index){const row=state.inventory[index];if(!row)return;const d=I.items[row.id],fx=d.effect;if(d.type==='artifact'){toggleArtifact(row.instanceId||row.id);return;}if(d.slot){equipGear(row.instanceId||row.id);return;}if(!fx||['ammo','loot','quest','weapon'].includes(d.type)){notify('Этот предмет нельзя использовать напрямую.');return;}if(fx.ammo)return notify('Боеприпасы можно зарядить в бою.');if(fx.repair)return notify('Снаряжение исправно.');for(const k of ['health','stamina'])if(fx[k])state.player[k]=clamp(state.player[k]+fx[k]*(k==='health'?1+(passive().healingBonus||0):1),0,k==='health'?finalStats().maxHealth:finalStats().maxStamina);for(const k of ['hunger','thirst','radiation'])if(fx[k])state.player[k]=clamp(state.player[k]+fx[k]);remove(row.id);notify(`Использован предмет: ${d.name}.`);if(fx.quest==='documents'){state.worldFlags.documentsFound=true;}
  }
  function equipGear(ref){const row=findItem(ref),item=I.items[row?.id],slot=item?.slot;if(!row||!slot||!['primary','sidearm','melee','armor','head','backpack','detector'].includes(slot))return notify('Этот предмет не подходит к слоту экипировки.');const old=state.equipment[slot];state.equipment[slot]=row.instanceId||row.id;if(['primary','sidearm','melee'].includes(slot))state.equipment.activeWeaponSlot=slot;syncWeaponAlias();state.player.health=Math.min(state.player.health,finalStats().maxHealth);state.player.stamina=Math.min(state.player.stamina,finalStats().maxStamina);notify('Экипировано: '+item.name+(old&&old!==(row.instanceId||row.id)?' вместо прежнего предмета.':'.')+(weight()>capacity()?' Вес выше лимита; предметы сохранены.':''));emit();}
