  function unequipSlot(slot){if(!['primary','sidearm','melee','armor','head','backpack','detector'].includes(slot)||!state.equipment[slot])return notify('Слот уже пуст.');const row=itemForSlot(slot),name=I.items[row?.id]?.name||'Снаряжение';state.equipment[slot]=null;if(slot===state.equipment.activeWeaponSlot){state.equipment.activeWeaponSlot=['sidearm','primary','melee'].find(key=>state.equipment[key])||'melee';syncWeaponAlias();}state.player.health=Math.min(state.player.health,finalStats().maxHealth);state.player.stamina=Math.min(state.player.stamina,finalStats().maxStamina);notify('Снято снаряжение: '+name+'.'+(weight()>capacity()?' Вес выше новой грузоподъёмности; вещи остались в рюкзаке.':''));emit();}
  function switchWeapon(slot){if(!['primary','sidearm','melee'].includes(slot)||!itemForSlot(slot))return notify('В этом слоте нет подходящего оружия.');state.equipment.activeWeaponSlot=slot;syncWeaponAlias();notify(`В руках: ${I.items[state.equipment.weapon].name}.`);emit();}
  function toggleArtifact(ref){const row=findItem(ref);if(!row||I.items[row.id]?.type!=='artifact')return notify('Артефакта нет в рюкзаке.');const instance=row.instanceId||row.id,list=state.equipment.artifacts,i=list.indexOf(instance);if(i>=0)list.splice(i,1);else if(list.length<4)list.push(instance);else return notify('Доступно четыре слота артефактов.');state.player.health=Math.min(state.player.health,finalStats().maxHealth);state.player.stamina=Math.min(state.player.stamina,finalStats().maxStamina);notify((i>=0?'Артефакт снят: ':'Артефакт экипирован: ')+I.items[row.id].name);emit();}
  function sell(ref,qty=1){const row=findItem(ref);if(!row||row.qty<qty)return notify('Предмета нет в рюкзаке.');const id=row.id;if(isEquipped(row.instanceId||row.id))return notify('Сначала сними экипированный предмет.');const npc=trader();if(!npc)return notify('Здесь нет торговца.');const factor=shopFactor(npc.faction),price=Math.max(1,Math.round(I.items[id].price*.52*factor));removeItem(ref,qty);gainMoney(price*qty);notify(`Продано ${I.items[id].name} ×${qty} за ${price*qty} ₽.`);emit();}
  function drop(ref){const row=findItem(ref);if(!row)return notify('Предмета нет в рюкзаке.');const id=row.id;if(isEquipped(row.instanceId||row.id))return notify('Сначала сними экипированный предмет.');removeItem(ref);notify(`Оставлено в Зоне: ${I.items[id].name}.`);emit();}
  function trader(){const loc=W.locations[state.player.location],npc=L.caravanAt(state)===state.player.location?W.people.v9_caravan:loc.trader?W.people[loc.trader]:null;return npc&&(state.reputation[npc.faction]||0)>-40?npc:null;}
  function buy(id,qty=1){const shop=getShop();if(!shop)return notify('Торговец сейчас недоступен.');const row=shop.stock.find(x=>x.id===id),item=I.items[id];if(!row||!item)return notify('Этой позиции сейчас нет в продаже.');if(!Number.isInteger(qty)||qty<1||(!item.stackable&&qty!==1))return notify('Недопустимое количество.');if(qty>row.quantity)return notify('Недостаточно товара в наличии.');const owned=count(id),limit=item.stackLimit;if(limit&&owned+qty>limit)return notify('Лимит стопки превышен.');const price=row.price*qty;if(state.player.money<price)return notify('Не хватает денег.');if(weight()+item.weight*qty>capacity()+1e-7)return notify('Рюкзак полон. Сними лишний вес.');if(add(id,qty)<qty)return notify('Рюкзак полон. Сними лишний вес.');state.traderStocks[shop.id].stock[id]-=qty;state.player.money-=price;notify('Куплено '+item.name+' ×'+qty+' за '+price+' ₽.');emit();}

  function breath(){
    if(state.event||state.combat||state.player.health<=0)return notify('Сначала закончи текущую встречу.');
    const p=state.player,before=p.stamina;p.stamina=clamp(p.stamina+25,0,finalStats().maxStamina);advanceClock(1);p.hunger=clamp(p.hunger+needDrain(3));p.thirst=clamp(p.thirst+needDrain(4));
    notify('Передышка в укрытии: +'+Math.round(p.stamina-before)+' выносливости. Прошёл час; голод и жажда усилились.');
  }
  function rest(){if(state.event||state.combat)return notify('Сначала закончи текущую встречу.');const npc=trader(),loc=W.locations[state.player.location];if(!npc&&!loc.camp)return notify('Здесь нет места для платного отдыха.');if(state.player.money<35)return notify('Недостаточно денег.');state.player.money-=35;advanceClock(2);state.player.health=clamp(state.player.health+25,0,finalStats().maxHealth);state.player.stamina=finalStats().maxStamina;state.player.hunger=clamp(state.player.hunger+7);state.player.thirst=clamp(state.player.thirst+8);state.player.radiation=clamp(state.player.radiation-4);notify('Передышка у костра: +25 здоровья, выносливость восстановлена, фон немного спал. Потрачено 35 ₽.');}
  // Access is derived from existing activity and authored current-stage choices, never a saved permission.
  function isNpcAvailable(id,location=state.player.location){return L.npcAvailable(state,id,location);}
  function eventQuestPermission(q,action,choice){
    const e=state.event,flow=e?.flow,def=W.events.find(x=>x.id===e?.id);
    if(!choice||!def||flow?.phase!=='choices'||state.combat||state.player.health<=0||['menu','background','dead'].includes(state.mode))return false;
    const stage=stagesOf(def).find(x=>x.id===flow.stageId);
    const match=stage?.choices?.find(c=>c.label===choice.label&&c.action===choice.action&&c.questId===choice.questId&&JSON.stringify(c.effects?.startQuest)===JSON.stringify(choice.effects?.startQuest));
    if(!match||!choiceAvailable(match)||flow.claimedActions.includes(e.id+':'+flow.stageId+':'+choice.label))return false;
    const explicit=action==='accept'?([].concat(match.effects?.startQuest||[]).includes(q.id)):(match.action==='turnIn'&&match.questId===q.id);
    if(!explicit)return false;
    // Field-story briefs are authored leads (notes/evidence), not remote conversations with a missing giver.
    if(def.questSource==='field'&&def.personalStory&&!def.storyContact&&action==='accept')return def.requiresBackground===state.backgroundId&&def.storyChapter===state.personalStory.currentChapter&&def.locations.includes(environmentId());
    if(def.questSource==='signal'&&action==='accept')return !def.locations||def.locations.includes(environmentId());
    const npc=def.npcId||(def.id.startsWith('npc_story_')?def.id.slice(10):null);
    const expected=action==='accept'?(q.giverNpcId||q.giver):(q.turnInNpcId||q.giver);
    return npc===expected&&isNpcAvailable(npc,environmentId());
  }
  function canInteractWithQuest(q,action,choice=null){
    if(!q)return {allowed:false,reason:'Поручение недоступно.'};
    if(action==='accept'&&!questUnlocked(q))return {allowed:false,reason:'Поручение пока недоступно.'};
    if(eventQuestPermission(q,action,choice))return {allowed:true,reason:''};
    if(state.event||state.combat||state.travelTo||state.expedition.active||state.explorationActive)return {allowed:false,reason:action==='accept'?'Нельзя взять задание во время исследования или встречи.':'Нельзя сдать задание во время исследования или встречи.'};
    if(['menu','background','dead'].includes(state.mode))return {allowed:false,reason:'Поручение сейчас недоступно.'};
    const npc=action==='accept'?(q.giverNpcId||q.giver):(q.turnInNpcId||q.giver);
    const locations=L.questLocations(state,q,action);
    if(!isNpcAvailable(npc)||!locations.includes(state.player.location))return {allowed:false,reason:'Этот персонаж сейчас недоступен здесь.'};
    return {allowed:true,reason:''};
  }
  function questChoiceAccess(choice){
    const ids=choice.action==='turnIn'?[choice.questId]:[].concat(choice.effects?.startQuest||[]);
    return ids.map(id=>canInteractWithQuest(W.quests.find(q=>q.id===id),choice.action==='turnIn'?'turnIn':'accept',choice)).find(x=>!x.allowed)||{allowed:true,reason:''};
  }
  function questOffers(){return W.quests.filter(q=>L.questLocations(state,q,'accept').includes(state.player.location)&&!state.quests.active.some(a=>a.id===q.id)&&!state.quests.completed.includes(q.id)&&questUnlocked(q)&&(!q.target||q.id!=='scout_pripyat'||state.known.includes('pripyat'))).map(q=>{const access=canInteractWithQuest(q,'accept');return {...q,giverLocations:L.questLocations(state,q,'accept'),turnInLocations:L.questLocations(state,q,'turnIn'),accepted:false,canAccept:access.allowed,acceptReason:access.reason};});}
  function acceptQuest(id,choice=null){const d=W.quests.find(q=>q.id===id);if(!d||!questUnlocked(d)||state.quests.completed.includes(id)||state.quests.active.some(q=>q.id===id) )return;const access=canInteractWithQuest(d,'accept',choice);if(!access.allowed){notify(access.reason);return false;}state.quests.active.push({id,step:d.type==='route'&&d.target===state.player.location?1:0,progress:0,searchAttempts:0,acceptedAtLocation:state.player.location});notify(`Принято задание: ${d.title}.`);}
  function npcAction(value){const [id,act]=value.split(':');const npc=W.people[id];if(!npc||!isNpcAvailable(id))return notify('Этого человека здесь нет.');if(state.event||state.combat)return notify('Сначала закончи текущую встречу.');if(npc.nonCombatant&&act!=='talk')return notify(npc.personalStory?'Личный знакомый не предлагает бой. Поговори с ним.':'Бандит — мирный талисман блокпоста.');if(act==='fight')return startCombat(npc.enemyId||(npc.faction==='military'?'military':npc.faction==='mercs'?'merc':npc.faction==='duty'?'duty':npc.faction==='monolith'?'monolith':npc.faction==='bandits'?'bandit':'rookie'));if(!npc.personalStory&&(state.reputation[npc.faction]||0)<=-40&&act!=='fight')return notify(npc.name+': разговор окончен. Сначала восстанови отношение группировки.');if(act==='quest'){state.mode='quests';emit();return;}if(act==='news'){action('news');return;}if(act==='talk'){const definition=W.events.find(event=>event.id==='npc_story_'+id);if(!definition)return notify('Собеседник сейчас не готов разговаривать.');const key='npc-met:'+id,met=Boolean(state.npcMemory[id]?.visits)||state.knowledge.includes(key);state.npcMemory[id]={...state.npcMemory[id],visits:(state.npcMemory[id]?.visits||0)+1,lastSeen:state.worldClock};if(!met)state.knowledge.push(key);startEvent(definition,'event');if(met&&!npc.nonCombatant){state.event.text=npc.name+' узнаёт тебя и кивает: «Снова ты. Помню нашу прошлую встречу». ';state.event.flow.history.push({text:npc.greeting,choice:'Вы уже встречались'});}emit();}}
  function turnIn(id,choice=null){const q=state.quests.active.find(x=>x.id===id);if(!q)return;const d=W.quests.find(x=>x.id===id);if(d.personalStory&&(d.backgroundId!==state.backgroundId||d.storyChapter!==state.personalStory.currentChapter))return notify('Это поручение относится к другой главе личной истории.');const access=canInteractWithQuest(d,'turnIn',choice);if(!access.allowed){notify(access.reason);return false;}if(d.type==='deliver'&&count(d.item)<(d.count||1))return notify(`Нужно принести: ${I.items[d.item].name} ×${d.count||1}.`);if(d.type==='deliverType'&&!state.inventory.some(x=>I.items[x.id].type===d.itemType))return notify('В рюкзаке нет нужного артефакта.');if(!questReady(id))return notify('Условия поручения ещё не выполнены.');if(d.type==='deliver')remove(d.item,d.count||1);if(d.type==='deliverType'){const art=state.inventory.find(x=>I.items[x.id].type===d.itemType);removeItem(art.instanceId||art.id,1);}if(['kill','explore'].includes(d.type)&&q.progress<(d.count||1))return notify(`Пока выполнено ${q.progress}/${d.count}.`);if(d.type==='route'&&state.player.location!==d.returnTo)return notify('Вернись в сектор «'+W.locations[d.returnTo].name+'».');completeQuest(q);emit();return true;}
  function showEventChoice(i){chooseEvent(i);}
  function getMap(){return Object.entries(W.locations).map(([id,l])=>({id,name:l.name,danger:l.danger,known:state.known.includes(id),visited:state.visited.includes(id),current:id===state.player.location,open:unlocked(id),neighbors:M.neighbors(state,id)}));}
  function questReady(id){const q=state.quests.active.find(q=>q.id===id),d=W.quests.find(d=>d.id===id);if(!q||!d)return false;if(id==='village_medic')return state.worldFlags.quietWellMedicalCrateFound===true;if(d.type==='visit')return state.visited.includes(d.target);if(d.type==='route')return q.step>=1;if(d.type==='deliver')return count(d.item)>=(d.count||1);if(d.type==='deliverType')return state.inventory.some(x=>I.items[x.id]?.type===d.itemType);if(['kill','explore','research','anomaly','personal'].includes(d.type))return q.progress>=(d.count||1);return false;}
  function getQuests(){return {active:state.quests.active.map(q=>{const d=W.quests.find(d=>d.id===q.id),ready=questReady(q.id),automatic=Boolean(state.settings.autoTurnInQuests&&d.autoTurnInEligible&&!d.requiresDialogue),progress=d.type==='deliver'?Math.min(d.count||1,count(d.item)):d.type==='deliverType'?Math.min(d.count||1,state.inventory.filter(x=>I.items[x.id]?.type===d.itemType).reduce((n,x)=>n+x.qty,0)):q.progress;return {...d,...q,giverLocations:L.questLocations(state,d,'accept'),turnInLocations:L.questLocations(state,d,'turnIn'),canPin:true,pinned:state.fieldJournal.pinned.includes(q.id),progress,ready,automatic,status:ready?'Готово к сдаче':progress>0||q.step>0?'Выполняется':'Не выполнено',canTurnIn:ready&&canInteractWithQuest(d,'turnIn').allowed,turnInReason:canInteractWithQuest(d,'turnIn').reason};}).sort((a,b)=>Number(b.pinned)-Number(a.pinned)),available:questOffers(),completed:state.quests.completed.map(id=>({...W.quests.find(q=>q.id===id),status:'Выполнено'}))};}
  const invalidShopItems=new Set();
  function getShop(){const who=trader();if(!who)return null;const id=Object.keys(W.people).find(id=>W.people[id]===who),record=state.traderStocks[id],fac=shopFactor(who.faction)*(1-Math.max(0,state.worldState.npcMemory[id]?.trust||0)*.01);for(const item of window.ZoneRPGShops.pools[id]||[])if(!I.items[item]&&!invalidShopItems.has(item)){invalidShopItems.add(item);console.warn('[ZoneRPG] Пропущена недопустимая позиция магазина',item);}
    return {id,name:who.name,faction:who.faction,day:record.day,stock:Object.entries(record.stock).filter(([item])=>{if(I.items[item]&&Number.isFinite(I.items[item].price)&&I.items[item].price>=0)return true;if(!invalidShopItems.has(item)){invalidShopItems.add(item);console.warn('[ZoneRPG] Пропущена недопустимая позиция магазина',item);}return false;}).map(([id,quantity])=>({id,item:I.items[id],quantity,price:Math.ceil(I.items[id].price*fac*(I.items[id].type==='medicine'?1+worldModifier('medicalPrice'):1))}))};
  }

  function die(){if(state.expedition.active)state.lastExpedition=clone(state.expedition);resetExploration();state.travelTo=null;state.player.health=0;state.mode='dead';state.deathSummary={trips:state.player.trips,kills:state.statistics.kills,artifacts:state.statistics.artifacts,earnings:state.statistics.earnings,quests:state.statistics.quests};state.combat=null;state.event=null;log('Ты погиб в Зоне. Последнее сохранение осталось нетронутым.');emit('death');}
  function loadSavedGame(type){const saved=window.ZoneRPGSave.read(type);if(!saved.ok){state.loadError=saved.reason==='corrupt'?'Сохранение повреждено. Его данные сохранены; можно начать новую игру или попробовать другую копию.':saved.reason==='empty'?'Сохранение отсутствует.':'Версия сохранения не поддерживается.';notify(state.loadError);return;}let restored;try{restored=S.sanitize(saved.data,I.items,W);}catch(error){console.error('[ZoneRPG] Не удалось восстановить сохранение',error);state.loadError='Не удалось восстановить сохранение. Исходная запись не изменена.';notify(state.loadError);return;}state=restored;expeditionReturn=false;if(state.expedition.active&&!state.expedition.details)F.begin(state);state.loadError=null;if(state.event?.flow?.phase==='choices'){const def=W.events.find(e=>e.id===state.event.id),stage=def&&stagesOf(def).find(s=>s.id===state.event.flow.stageId);if(stage?.text)state.event.text=stage.text;L.decorate(state,state.event);window.ZoneRPGNarrative.contact(state,state.event);}if(state.travelTo&&!state.event&&!state.combat)arrive(state.travelTo);notify('Сохранение загружено.');}
  // Eligible automatic delivery is opt-in and never skips a story/dialogue choice.
  function environmentId(){return state.travelTo||state.player.location;}
