  function questSearch(id){if(state.event||state.combat||state.expedition.active||state.travelTo)return notify('Сначала завершите текущую встречу или вылазку.');const q=state.quests.active.find(q=>q.id===id),d=W.quests.find(d=>d.id===id);if(!q||!d||questReady(id))return;const loc=d.searchLocation||d.target;if(loc!==state.player.location)return notify('Поиск доступен в секторе '+W.locations[loc].name+'.');const eventId=id==='village_medic'?'v103_medical_crate':id==='field_notes'?'v72_document_search':d.type==='anomaly'?'v72_anomaly_'+id:null;if(eventId)startEvent(W.events.find(e=>e.id===eventId),'event');}
  function documentSearch(){const q=state.quests.active.find(q=>q.id==='field_notes');if(!q||state.player.location!=='yantar')return 'Нет активного поручения на документы.';if(count('documents'))return 'Документы уже в рюкзаке. Вернись к учёному.';q.searchAttempts=Math.min(3,(q.searchAttempts||0)+1);if(q.searchAttempts<3&&Math.random()>.25*q.searchAttempts)return 'Найдена маркировка следующей ниши. Поиск '+q.searchAttempts+'/3; следующая попытка ближе к архиву.';if(!add('documents',1))return 'Архив найден, но рюкзак полон. Освободи место; следующий поиск снова приведёт сюда.';state.worldFlags.documentsFound=true;return 'Найден полевой журнал лаборатории. Документы в рюкзаке; задание готово к сдаче учёному.';}
