  function postCombatOutcome(kind){const flow=state.event?.flow,type=flow?.flags.combatWon,enemy=W.enemyTypes[type];if(!enemy)return 'Противник не побеждён: добыча осталась у него. Ты отмечаешь направление отхода.';const key='postCombat:'+kind;if(flow.flags[key])return 'Эта часть места боя уже проверена.';flow.flags[key]=true;let text='';if((enemy.kind==='mutant'||enemy.faction==='mutants')&&['salvage','biological'].includes(kind)){const got=add('mutantParts',1);text=got?'Собран биологический образец мутанта.':'Образец пришлось оставить: рюкзак полон.';}else if(kind==='body'){const ammo=I.weapons[enemy.weapon]?.ammoType;if(ammo){const got=add(ammo,3);text=got?'Дополнительно найдено '+got+' патрона: '+I.items[ammo].name+'.':'Патроны пришлось оставить: рюкзак полон.';}else{grantXP(4,'полевые наблюдения');text='Образец следа и состояние костяных пластин записаны в КПК. +4 опыта.';}}else if(kind==='clue'){maybeReveal();const ammo=I.weapons[enemy.weapon]?.ammoType,got=ammo?add(ammo,3):0;text='Ты обходишь место боя и отмечаешь тропу к укрытию в КПК.'+(ammo?(got?' У укрытия сохранился запас патронов.':' Патроны пришлось оставить: рюкзак полон.'):' Боеприпасов среди следов мутанта нет.');}else if(kind==='study'){grantXP(6,'изучение противника');text='Особенности '+enemy.name+' записаны в справочник. +6 опыта.';}else{const ammo=I.weapons[enemy.weapon]?.ammoType,id=ammo||'parts',got=add(id,ammo?2:1);text=got?'При осмотре укрытия получено: '+I.items[id].name+' ×'+got+'.':'Полезные остатки найдены, но для них нет места.';}state.knowledge=[...new Set([...state.knowledge,'После боя: '+enemy.name+'. '+text])].slice(-80);return text;}
