  const autosaveActions=new Set(['pinQuest','readJournal','openPanel','notebook','renamePlayer','startGame','zoneAction','zonePOI','zoneStudy','zoneService','livingAction','storyAction','claimStoryRewards','questSearch','researchQuest','joinFaction','leaveFaction','travel','investAttribute','explore','event','eventReturn','attack','aim','defend','flee','combatUse','use','reload','equipGear','equipSlot','equipWeapon','equipArmor','unequipSlot','switchWeapon','artifact','drop','buy','sell','breath','rest','npcAction','acceptQuest','turnIn','dismissEvent']);
